```
using System;

namespace Calculator
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Calculator");
            Console.WriteLine("Enter first number: ");
            double num1 = double.Parse(Console.ReadLine());
            Console.WriteLine("Enter second number: ");
            double num2 = double.Parse(Console.ReadLine());
            Console.WriteLine("Enter operation (+, -, *, /): ");
            char operation = char.Parse(Console.ReadLine());
            double result;

            switch (operation)
            {
                case '+':
                    result = num1 + num2;
                    Console.WriteLine("Result: " + result);
                    break;
                case '-':
                    result = num1 - num2;
                    Console.WriteLine("Result: " + result);
                    break;
                case '*':
                    result = num1 * num2;
                    Console.WriteLine("Result: " + result);
                    break;
                case '/':
                    if (num2 != 0)
                    {
                        result = num1 / num2;
                        Console.WriteLine("Result: " + result);
                    }
                    else
                    {
                        Console.WriteLine("Cannot divide by zero.");
                    }
                    break;
                default:
                    Console.WriteLine("Invalid operation.");
                    break;
            }
        }
    }
}
```

def longest_consecutive_subsequence(lst):
    if not lst: return []
    lst = sorted(set(lst))
    max_len, current_len = 1, 1
    longest_seq_start = lst[0]
    current_seq_start = lst[0]

    for i in range(1, len(lst)):
        if lst[i] - lst[i - 1] == 1:
            current_len += 1
            if current_len > max_len:
                max_len = current_len
                longest_seq_start = current_seq_start
        else:
            current_len = 1
            current_seq_start = lst[i]

    return list(range(longest_seq_start, longest_seq_start + max_len))

numbers = [4, 2, 1, 6, 5]
print(longest_consecutive_subsequence(numbers))  # Output: [4, 5, 6]

